"""Injected application failures, not errors generated by a model."""
import asyncio
import json
from pathlib import Path
from executor import Executor

async def main(output='outputs/injected_failures.json'):
    def broken(**kwargs):raise RuntimeError('Injected exception')
    cases=[('bad_type','get_machine_spec',{'machine_id':['CONV-3']},None),
           ('unknown_tool','delete_records',{'machine_id':'CONV-3'},None),
           ('bad_window','query_temperature',{'machine_id':'CONV-3','start':'2026-03-02T11:00:00+08:00','end':'2026-03-02T10:00:00+08:00'},None),
           ('tool_exception','get_machine_spec',{'machine_id':'CONV-3'},broken),
           ('wrong_but_valid_machine','get_machine_spec',{'machine_id':'CONV-7'},None)]
    rows=[]
    for name,tool,args,replacement in cases:
        ex=Executor()
        if replacement:ex.handlers['get_machine_spec']=replacement
        result=await ex.execute(tool,json.dumps(args))
        rows.append({'case':name,'injected':True,'result':result,'events':ex.events})
    path=Path(output);path.parent.mkdir(parents=True,exist_ok=True)
    if path.exists():raise ValueError('Choose a fresh evidence output path.')
    path.write_text(json.dumps(rows,indent=2),encoding='utf-8');print('Saved',path)

if __name__=='__main__':asyncio.run(main())
